				height: size,
				borderRadius: size / 2,
				backgroundColor: theme.primary,
				alignItems: "center",
				justifyContent: "center",
			}}
		>
			<ThemedText type="smallBold" themeColor="primaryForeground">
				{initials || "?"}
			</ThemedText>
